import combinationsReplacement from '../../src/combinations_replacement.js';

describe('combinationsReplacement', () => {
  test('produces all 2-combinations with repetition for [1, 2, 3]', () => {
    const result = combinationsReplacement([1, 2, 3], 2);
    const expected = [
      [1, 1],
      [1, 2],
      [1, 3],
      [2, 2],
      [2, 3],
      [3, 3],
    ];
    expect(result).toEqual(expected);
  });

  test('returns single-element combinations when k = 1', () => {
    const result = combinationsReplacement([1, 2, 3], 1);
    const expected = [[1], [2], [3]];
    expect(result).toEqual(expected);
  });

  test('returns empty array when input is empty', () => {
    const result = combinationsReplacement([], 3);
    expect(result).toEqual([]);
  });

  test('handles duplicates in input by producing duplicates in output', () => {
    const result = combinationsReplacement([1, 1], 2);
    // From analysis: [1,1], [1,1], [1,1] (three identical combinations)
    const expected = [[1, 1], [1, 1], [1, 1]];
    expect(result).toEqual(expected);
  });

  test('produces all 3-combinations with repetition for [1, 2, 3]', () => {
    const result = combinationsReplacement([1, 2, 3], 3);
    const expected = [
      [1, 1, 1],
      [1, 1, 2],
      [1, 1, 3],
      [1, 2, 2],
      [1, 2, 3],
      [1, 3, 3],
      [2, 2, 2],
      [2, 2, 3],
      [2, 3, 3],
      [3, 3, 3],
    ];
    expect(result).toEqual(expected);
  });
});

