import chiSquaredGoodnessOfFit from '../../src/chi_squared_goodness_of_fit.js';

describe('chiSquaredGoodnessOfFit', () => {
  test('returns true when chi-squared statistic exceeds the critical value', () => {
    const data = [
      ...Array(5).fill(0),
      ...Array(3).fill(1),
      ...Array(2).fill(2),
      ...Array(2).fill(3),
    ];

    const distributionType = () => ({
      0: 0.25,
      1: 0.25,
      2: 0.25,
      3: 0.25,
    });

    const result = chiSquaredGoodnessOfFit(data, distributionType, 0);
    expect(result).toBe(true);
  });

  test('returns false when chi-squared statistic does not exceed the critical value', () => {
    const data = [
      ...Array(5).fill(0),
      ...Array(3).fill(1),
      ...Array(4).fill(2),
      ...Array(4).fill(3),
    ];

    const distributionType = () => ({
      0: 0.25,
      1: 0.25,
      2: 0.25,
      3: 0.25,
    });

    const result = chiSquaredGoodnessOfFit(data, distributionType, 0);
    expect(result).toBe(false);
  });
});

