import poissonDistribution from '../../src/poisson_distribution.js';

describe('poissonDistribution', () => {
  test('returns undefined for non-positive lambda', () => {
    expect(poissonDistribution(0)).toBeUndefined();
    expect(poissonDistribution(-1)).toBeUndefined();
  });

  test('first value equals exp(-lambda)', () => {
    const lambda = 1;
    const cells = poissonDistribution(lambda);
    expect(Array.isArray(cells)).toBe(true);
    expect(cells.length).toBeGreaterThan(0);
    expect(cells[0]).toBeCloseTo(Math.exp(-lambda), 1e-12);
  });

  test('second value equals exp(-lambda) * lambda when present', () => {
    const lambda = 2;
    const cells = poissonDistribution(lambda);
    if (cells.length > 1) {
      expect(cells[1]).toBeCloseTo(Math.exp(-lambda) * lambda, 1e-12);
    }
  });

  test('sum of probabilities is less than or equal to 1', () => {
    const lambda = 5;
    const cells = poissonDistribution(lambda);
    const sum = cells.reduce((a, b) => a + b, 0);
    expect(sum).toBeLessThanOrEqual(1);
  });

  test('values are finite numbers and non-NaN', () => {
    const lambda = 0.7;
    const cells = poissonDistribution(lambda);
    expect(cells.length).toBeGreaterThan(0);
    for (const v of cells) {
      expect(typeof v).toBe('number');
      expect(Number.isFinite(v)).toBe(true);
      expect(Number.isNaN(v)).toBe(false);
    }
  });
});

