const mod = require('../../src/permutations_heap');
const permutationsHeap = mod.default || mod;

describe('permutationsHeap', () => {
  test('generates all permutations for [1,2,3] in Heap order', () => {
    const input = [1, 2, 3];
    const result = permutationsHeap(input.slice());
    expect(result).toEqual([
      [1, 2, 3],
      [2, 1, 3],
      [3, 1, 2],
      [1, 3, 2],
      [2, 3, 1],
      [3, 2, 1],
    ]);
  });

  test('returns single empty permutation for empty input', () => {
    const res = permutationsHeap([]);
    expect(res).toEqual([[]]);
  });

  test('returns single permutation for single element array', () => {
    const res = permutationsHeap([42]);
    expect(res).toEqual([[42]]);
  });

  test('generates permutations for two elements in correct order', () => {
    const res = permutationsHeap(['a', 'b']);
    expect(res).toEqual([
      ['a', 'b'],
      ['b', 'a'],
    ]);
  });

  test('all results are permutations of input (n=4)', () => {
    const input = [1, 2, 3, 4];
    const res = permutationsHeap(input.slice());
    expect(res.length).toBe(24);
    const sortedOriginal = input.slice().sort();
    res.forEach(arr => {
      expect(arr.slice().sort()).toEqual(sortedOriginal);
    });
  });
});
